<script setup lang="ts">
import { onMounted, ref } from 'vue'; import AppShell from '@/layouts/AppShell.vue'; import PageHeader from '@/components/PageHeader.vue'; import PanelCard from '@/components/PanelCard.vue'; import { connect } from '@/services/connect'; import type { ConnectionItem } from '@/types/domain'; const instances=ref<ConnectionItem[]>([]),selected=ref(''),calls=ref<any[]>([]); async function load(){if(!selected.value)return; const r:any=await connect.calls(selected.value).catch(()=>[]); calls.value=Array.isArray(r)?r:Array.isArray(r?.data)?r.data:[]}; onMounted(async()=>{instances.value=await connect.connections().catch(()=>[]);selected.value=instances.value[0]?.id||'';await load()})
</script>
<template><AppShell><PageHeader title="Chamadas" description="Acompanhe a comunicação por voz."/><div class="toolbar"><select v-model="selected" class="select" @change="load"><option v-for="i in instances" :key="i.id" :value="i.id">{{i.name}}</option></select></div><PanelCard title="Chamadas atuais"><div v-if="calls.length" class="data-list"><div v-for="(c,i) in calls" :key="c.id||i"><span>{{c.number || c.remoteJid || c.to || 'Chamada'}}</span><strong>{{c.status || c.state || 'Em andamento'}}</strong></div></div><p v-else class="muted-block">Nenhuma chamada ativa neste momento.</p></PanelCard></AppShell></template>
